498	    async fn open_at(
499	        &mut self,
500	        fd: Resource<types::Descriptor>,
501	        path_flags: types::PathFlags,
502	        path: String,
503	        oflags: types::OpenFlags,
504	        flags: types::DescriptorFlags,
505	    ) -> FsResult<Resource<types::Descriptor>> {
506	        use cap_fs_ext::{FollowSymlinks, OpenOptionsFollowExt, OpenOptionsMaybeDirExt};
507	        use system_interface::fs::{FdFlags, GetSetFdFlags};
508	        use types::{DescriptorFlags, OpenFlags};
509	
510	        let allow_blocking_current_thread = self.ctx().allow_blocking_current_thread;
511	        let table = self.table();
512	        let d = table.get(&fd)?.dir()?;
513	        if !d.perms.contains(DirPerms::READ) {
514	            Err(ErrorCode::NotPermitted)?;
515	        }
516	
517	        if !d.perms.contains(DirPerms::MUTATE) {
518	            if oflags.contains(OpenFlags::CREATE) || oflags.contains(OpenFlags::TRUNCATE) {
519	                Err(ErrorCode::NotPermitted)?;
520	            }
521	            if flags.contains(DescriptorFlags::WRITE) {
522	                Err(ErrorCode::NotPermitted)?;
523	            }
524	        }
525	
526	        // Track whether we are creating file, for permission check:
527	        let mut create = false;
528	        // Track open mode, for permission check and recording in created descriptor:
529	        let mut open_mode = OpenMode::empty();
530	        // Construct the OpenOptions to give the OS:
531	        let mut opts = cap_std::fs::OpenOptions::new();
532	        opts.maybe_dir(true);
533	
534	        if oflags.contains(OpenFlags::CREATE) {
535	            if oflags.contains(OpenFlags::EXCLUSIVE) {
536	                opts.create_new(true);
537	            } else {
538	                opts.create(true);
539	            }
540	            create = true;
541	            opts.write(true);
542	            open_mode |= OpenMode::WRITE;
543	        }
544	
545	        if oflags.contains(OpenFlags::TRUNCATE) {
546	            opts.truncate(true).write(true);
547	        }
548	        if flags.contains(DescriptorFlags::READ) {
549	            opts.read(true);
550	            open_mode |= OpenMode::READ;
551	        }
552	        if flags.contains(DescriptorFlags::WRITE) {
553	            opts.write(true);
554	            open_mode |= OpenMode::WRITE;
555	        } else {
556	            // If not opened write, open read. This way the OS lets us open
557	            // the file, but we can use perms to reject use of the file later.
558	            opts.read(true);
559	            open_mode |= OpenMode::READ;
560	        }
561	        if symlink_follow(path_flags) {
562	            opts.follow(FollowSymlinks::Yes);
563	        } else {
564	            opts.follow(FollowSymlinks::No);
565	        }
566	
567	        // These flags are not yet supported in cap-std:
568	        if flags.contains(DescriptorFlags::FILE_INTEGRITY_SYNC)
569	            || flags.contains(DescriptorFlags::DATA_INTEGRITY_SYNC)
570	            || flags.contains(DescriptorFlags::REQUESTED_WRITE_SYNC)
571	        {
572	            Err(ErrorCode::Unsupported)?;
573	        }
574	
575	        if oflags.contains(OpenFlags::DIRECTORY) {
576	            if oflags.contains(OpenFlags::CREATE)
577	                || oflags.contains(OpenFlags::EXCLUSIVE)
578	                || oflags.contains(OpenFlags::TRUNCATE)
579	            {
580	                Err(ErrorCode::Invalid)?;
581	            }
582	        }
583	
584	        // Now enforce this WasiCtx's permissions before letting the OS have
585	        // its shot:
586	        if !d.perms.contains(DirPerms::MUTATE) && create {
587	            Err(ErrorCode::NotPermitted)?;
588	        }
589	        if !d.file_perms.contains(FilePerms::WRITE) && open_mode.contains(OpenMode::WRITE) {
590	            Err(ErrorCode::NotPermitted)?;
591	        }
592	
593	        // Represents each possible outcome from the spawn_blocking operation.
594	        // This makes sure we don't have to give spawn_blocking any way to
595	        // manipulate the table.
596	        enum OpenResult {
597	            Dir(cap_std::fs::Dir),
598	            File(cap_std::fs::File),
599	            NotDir,
600	        }
601	
602	        let opened = d
603	            .spawn_blocking::<_, std::io::Result<OpenResult>>(move |d| {
604	                let mut opened = d.open_with(&path, &opts)?;
605	                if opened.metadata()?.is_dir() {
606	                    Ok(OpenResult::Dir(cap_std::fs::Dir::from_std_file(
607	                        opened.into_std(),
608	                    )))
609	                } else if oflags.contains(OpenFlags::DIRECTORY) {
610	                    Ok(OpenResult::NotDir)
611	                } else {
612	                    // FIXME cap-std needs a nonblocking open option so that files reads and writes
613	                    // are nonblocking. Instead we set it after opening here:
614	                    let set_fd_flags = opened.new_set_fd_flags(FdFlags::NONBLOCK)?;
615	                    opened.set_fd_flags(set_fd_flags)?;
616	                    Ok(OpenResult::File(opened))
617	                }
618	            })
619	            .await?;
620	
621	        match opened {
622	            OpenResult::Dir(dir) => Ok(table.push(Descriptor::Dir(Dir::new(
623	                dir,
624	                d.perms,
625	                d.file_perms,
626	                open_mode,
627	                allow_blocking_current_thread,
628	            )))?),
629	
630	            OpenResult::File(file) => Ok(table.push(Descriptor::File(File::new(
631	                file,
632	                d.file_perms,
633	                open_mode,
634	                allow_blocking_current_thread,
635	            )))?),
636	
637	            OpenResult::NotDir => Err(ErrorCode::NotDirectory.into()),
638	        }
639	    }
