641	    fn drop(&mut self, fd: Resource<types::Descriptor>) -> anyhow::Result<()> {
642	        let table = self.table();
643	
644	        // The Drop will close the file/dir, but if the close syscall
645	        // blocks the thread, I will face god and walk backwards into hell.
646	        // tokio::fs::File just uses std::fs::File's Drop impl to close, so
647	        // it doesn't appear anyone else has found this to be a problem.
648	        // (Not that they could solve it without async drop...)
649	        table.delete(fd)?;
650	
651	        Ok(())
652	    }
