4	unsafe fn test_file_truncation(dir_fd: wasi::Fd) {
5	    const FILENAME: &str = "test.txt";
6	
7	    // Open a file for writing
8	    let file_fd = wasi::path_open(
9	        dir_fd,
10	        0,
11	        FILENAME,
12	        wasi::OFLAGS_CREAT,
13	        wasi::RIGHTS_FD_WRITE,
14	        0,
15	        0,
16	    )
17	    .expect("creating a file for writing");
18	
19	    // Write to the file
20	    let content = b"this content will be truncated!";
21	    let nwritten = wasi::fd_write(
22	        file_fd,
23	        &[wasi::Ciovec {
24	            buf: content.as_ptr() as *const _,
25	            buf_len: content.len(),
26	        }],
27	    )
28	    .expect("writing file content");
29	    assert_eq!(nwritten, content.len(), "nwritten bytes check");
30	
31	    wasi::fd_close(file_fd).expect("closing the file");
32	
33	    // Open the file for truncation
34	    let file_fd = wasi::path_open(
35	        dir_fd,
36	        0,
37	        FILENAME,
38	        wasi::OFLAGS_CREAT | wasi::OFLAGS_TRUNC,
39	        wasi::RIGHTS_FD_WRITE | wasi::RIGHTS_FD_READ,
40	        0,
41	        0,
42	    )
43	    .expect("creating a truncated file for reading");
44	
45	    // Read the file's contents
46	    let buffer = &mut [0u8; 100];
47	    let nread = wasi::fd_read(
48	        file_fd,
49	        &[wasi::Iovec {
50	            buf: buffer.as_mut_ptr(),
51	            buf_len: buffer.len(),
52	        }],
53	    )
54	    .expect("reading file content");
55	
56	    // The file should be empty due to truncation
57	    assert_eq!(nread, 0, "expected an empty file after truncation");
58	
59	    wasi::fd_close(file_fd).expect("closing the file");
60	}
