        Ok(_) => panic!("truncating a read-only file should fail"),
        Err(e) => assert_eq!(
            e,
            ErrorCode::NotPermitted,
            "expected NotPermitted when truncating without write permission"
        ),
    }

    // The file must not have been truncated.
    assert_eq!(
        read_file_contents(dir),
        CONTENTS,
        "file contents after attempted truncation"
    );
